  function el(tag,cls,text){const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;}
  function icon(r){const n=el('span','site-icon');n.setAttribute('aria-hidden','true');const p=palettes[r.tone??r.id.split('').reduce((s,c)=>s+c.charCodeAt(0),0)%palettes.length];n.style.setProperty('--icon-bg',p[0]);n.style.setProperty('--icon-fg',p[1]);if(r.icon){const img=el('img');img.src=r.icon;img.alt='';n.append(img);}else n.textContent=r.mark||r.name.slice(0,2);return n;}
